import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

from azure.identity import ClientSecretCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def _parse_time(value: Optional[str], default: datetime) -> datetime:
    if not value:
        return default
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return default
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def query_recent_metric_datapoints(
    resource_id: str,
    metric_name: str,
    start_time: Optional[str] = None,
    end_time: Optional[str] = None,
    timespan_minutes: int = 60,
    aggregation: str = "Average",
    namespace: Optional[str] = None,
) -> List[Dict[str, Any]]:
    tenant_id = os.environ.get("AZURE_TENANT_ID")
    client_id = os.environ.get("AZURE_CLIENT_ID")
    client_secret = os.environ.get("AZURE_CLIENT_SECRET")

    if not all([tenant_id, client_id, client_secret]):
        raise EnvironmentError(
            "AZURE_TENANT_ID, AZURE_CLIENT_ID, and AZURE_CLIENT_SECRET must be set"
        )

    credential = ClientSecretCredential(
        tenant_id=tenant_id,
        client_id=client_id,
        client_secret=client_secret,
    )
    client = MetricsQueryClient(credential)

    now = datetime.now(timezone.utc)
    end_dt = _parse_time(end_time, now)
    start_dt = _parse_time(start_time, end_dt - timedelta(minutes=timespan_minutes))
    if start_dt > end_dt:
        start_dt, end_dt = end_dt - timedelta(minutes=timespan_minutes), end_dt

    agg_map = {
        "Average": MetricAggregationType.AVERAGE,
        "Minimum": MetricAggregationType.MINIMUM,
        "Maximum": MetricAggregationType.MAXIMUM,
        "Total": MetricAggregationType.TOTAL,
        "Count": MetricAggregationType.COUNT,
    }
    agg = agg_map.get(aggregation, MetricAggregationType.AVERAGE)

    response = client.query_resource(
        resource_uri=resource_id,
        metric_names=[metric_name],
        timespan=(start_dt, end_dt),
        granularity=None,
        aggregations=[agg],
        metric_namespace=namespace,
    )

    points: List[Dict[str, Any]] = []
    for metric in response.metrics:
        for timeseries in metric.timeseries:
            for data_point in timeseries.data:
                points.append(
                    {
                        "metric": metric.name.value if hasattr(metric.name, "value") else metric.name,
                        "timestamp": getattr(data_point, "timestamp", None).isoformat()
                        if getattr(data_point, "timestamp", None)
                        else None,
                        "average": getattr(data_point, "average", None),
                        "minimum": getattr(data_point, "minimum", None),
                        "maximum": getattr(data_point, "maximum", None),
                        "total": getattr(data_point, "total", None),
                        "count": getattr(data_point, "count", None),
                    }
                )

    return points
